package com.example.takura.media.infrastructure;
import jakarta.annotation.PostConstruct;import org.springframework.beans.factory.annotation.Value;import org.springframework.context.annotation.Profile;import org.springframework.stereotype.Component;
@Component @Profile("production") class ProductionStorageGuard {private final String endpoint,access,quarantine,privateBucket,publicBucket;ProductionStorageGuard(@Value("${takura.storage.endpoint:}")String endpoint,@Value("${takura.storage.access-key:}")String access,@Value("${takura.storage.quarantine-bucket:}")String quarantine,@Value("${takura.storage.private-bucket:}")String privateBucket,@Value("${takura.storage.public-bucket:}")String publicBucket){this.endpoint=endpoint;this.access=access;this.quarantine=quarantine;this.privateBucket=privateBucket;this.publicBucket=publicBucket;}@PostConstruct void validate(){if(!endpoint.isBlank()||!access.isBlank()||quarantine.endsWith("-local")||privateBucket.endsWith("-local")||publicBucket.endsWith("-local"))throw new IllegalStateException("Production refuses local storage endpoints, static credentials and local bucket names");if(quarantine.equals(privateBucket)||quarantine.equals(publicBucket)||privateBucket.equals(publicBucket))throw new IllegalStateException("Production storage boundaries must use distinct buckets");}}
